      successMetric: g.success_metric?.trim().slice(0, 500) || null,
      dueAt: g.due_at && /^\d{4}-\d{2}-\d{2}$/.test(g.due_at) ? g.due_at : null,
      isUpdateOf: g.is_update_of && ids.has(g.is_update_of) ? g.is_update_of : null,
      quote: g.quote.trim()
